const items = $input.all();

const requiredFields = [
  'signal_id',
  'source_type',
  'source_name',
  'signal_date',
  'market',
  'opportunity_category',
  'opportunity_title',
  'problem',
  'target_customer',
  'demand_signal',
  'proposed_solution',
  'monetization_model',
  'delivery_method',
  'geography',
  'evidence_notes'
];

const regulatedKeywords = [
  'health',
  'medical',
  'medicine',
  'pharma',
  'pharmaceutical',
  'therapy',
  'diagnosis',
  'patient',
  'finance',
  'financial',
  'investment',
  'investing',
  'loan',
  'lending',
  'credit',
  'insurance',
  'legal',
  'lawyer',
  'attorney',
  'employment screening',
  'background check',
  'government',
  'privacy',
  'personal data'
];

// Section 25/26 compliance co-occurrence fix. Root cause of confirmed false
// positives: a bare substring match on a regulated-industry word anywhere in
// the text, with no requirement that the record actually be describing a
// regulated offering. Fixed with a POSITIVE requirement (not a growing
// exclusion blocklist): a regulated keyword only counts if self-description/
// offering language co-occurs in the SAME sentence/paragraph chunk. An
// ambiguous case -- keyword present, no self-description language anywhere
// -- still does NOT flag: deliberately accepted, since that is exactly the
// false-positive shape found empirically, not genuine ambiguity the gate
// wants preserved on the conservative side.
const SELF_DESCRIPTION_PATTERNS = [
  /\b(we|i|our team)\s+(are\s+)?(build(?:s|ing)?|offer(?:s|ing)?|provide?(?:s|ing)?|operate?(?:s|ing)?|run(?:s|ning)?|sell(?:s|ing)?|develop(?:s|ing)?|deliver(?:s|ing)?|creat(?:e|es|ing)|found(?:ed|ing)?|launch(?:ed|es|ing)?)\b/i,
  /\b(we're|i'm|we are|i am)\s+(building|offering|providing|operating|running|selling|developing|delivering|creating|launching)\b/i,
  /\bour\s+(platform|product|service|company|tool|app|startup|business)\b/i,
  /\b(is|are|'s)\s+a\s+[a-z\s]{0,25}?(platform|product|service|company|tool|app|startup|business)\s+for\b/i,
  /\bin\s+the\s+[a-z\s]{0,25}?(industry|space|sector)\b/i,
];

function splitIntoChunks(text) {
  return text.split(/<p>|(?<=[.!?])\s+/).filter(Boolean);
}

function hasSelfDescription(chunk) {
  return SELF_DESCRIPTION_PATTERNS.some((re) => re.test(chunk));
}

function classifyCompliance(searchableText) {
  const chunks = splitIntoChunks(searchableText);
  const matchedKeywords = new Set();
  chunks.forEach((chunk) => {
    const chunkKeywords = regulatedKeywords.filter((kw) => chunk.includes(kw));
    if (chunkKeywords.length > 0 && hasSelfDescription(chunk)) {
      chunkKeywords.forEach((kw) => matchedKeywords.add(kw));
    }
  });
  return [...matchedKeywords];
}

return items.map((item) => {
  const data = item.json;

  const missingFields = requiredFields.filter((field) => {
    const value = data[field];
    return (
      value === undefined ||
      value === null ||
      String(value).trim() === ''
    );
  });

  const searchableText = [
    data.market,
    data.opportunity_title,
    data.problem,
    data.target_customer,
    data.demand_signal,
    data.proposed_solution,
    data.evidence_notes
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  const matchedRegulatedKeywords = classifyCompliance(searchableText);

  const isSynthetic =
    String(data.source_type || '').toLowerCase() === 'manual_test' ||
    String(data.evidence_notes || '').toLowerCase().includes('synthetic test');

  const sourceUrl = String(data.source_url || '').trim().toLowerCase();
  const evidenceSourceMissing =
    !isSynthetic &&
    (
      sourceUrl === '' ||
      sourceUrl === 'n/a' ||
      sourceUrl === 'na' ||
      sourceUrl === 'none'
    );

  return {
    json: {
      ...data,
      uor_stage: 'intake_validated',
      processed_at: new Date().toISOString(),
      required_field_count: requiredFields.length,
      missing_required_fields: missingFields,
      missing_required_field_count: missingFields.length,
      intake_valid: missingFields.length === 0,
      is_synthetic: isSynthetic,
      evidence_status: isSynthetic
        ? 'SYNTHETIC_TEST_ONLY'
        : 'REQUIRES_EVIDENCE_REVIEW',
      evidence_source_missing: evidenceSourceMissing,
      compliance_review_required: matchedRegulatedKeywords.length > 0,
      compliance_keywords_detected: matchedRegulatedKeywords,
      opportunity_score_status: 'NOT_SCORED',
      evidence_confidence_status: 'NOT_SCORED'
    }
  };
});

const aiItems = $input.all();
const intakeItems = $('Intake Validation').all();

const expectedFactorKeys = [
  'demand_signal_strength',
  'revenue_potential',
  'competition_level',
  'fulfillment_difficulty',
  'automation_potential',
  'recurring_revenue_potential',
  'scalability',
  'compatibility_with_existing_stack',
  'speed_to_first_revenue',
  'customer_acquisition_difficulty',
  'evidence_directness',
  'evidence_sample_size',
  'evidence_notes_summary'
];

function stripCodeFences(text) {
  return String(text)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

return aiItems.map((item, index) => {
  const intakeData = intakeItems[index]?.json || {};
  const data = item.json;

  const rawText = data?.content?.[0]?.text ?? null;

  let parsed = null;
  let parseError = null;

  if (rawText) {
    try {
      parsed = JSON.parse(stripCodeFences(rawText));
    } catch (err) {
      parseError = err.message;
    }
  } else {
    parseError = 'No text content found in AI response';
  }

  const missingFactorKeys = parsed
    ? expectedFactorKeys.filter((key) => !(key in parsed))
    : [...expectedFactorKeys];

  const structuredOutputValid = parsed !== null && missingFactorKeys.length === 0;

  return {
    json: {
      ...intakeData,
      ai_extracted_factors: parsed,
      ai_raw_response: rawText,
      structured_output_valid: structuredOutputValid,
      structured_output_parse_error: parseError,
      missing_factor_keys: missingFactorKeys,
      uor_stage: 'structured_output',
      structured_output_processed_at: new Date().toISOString()
    }
  };
});

const items = $input.all();

const directFactors = [
  'demand_signal_strength',
  'revenue_potential',
  'automation_potential',
  'recurring_revenue_potential',
  'scalability',
  'compatibility_with_existing_stack',
  'speed_to_first_revenue'
];

const inverseFactors = [
  'competition_level',
  'fulfillment_difficulty',
  'customer_acquisition_difficulty'
];

const totalFactorsConsidered = directFactors.length + inverseFactors.length;

function numericEstimate(factorObj) {
  if (!factorObj) return null;
  const val = factorObj.estimate;
  return typeof val === 'number' ? val : null;
}

return items.map((item) => {
  const data = item.json;

  if (!data.structured_output_valid || !data.ai_extracted_factors) {
    return {
      json: {
        ...data,
        uor_stage: 'initial_factor_scoring',
        opportunity_score: null,
        opportunity_score_status: 'BLOCKED_INVALID_STRUCTURED_OUTPUT',
        scoring_factor_coverage: null,
        evidence_confidence: null,
        evidence_confidence_status: 'BLOCKED_INVALID_STRUCTURED_OUTPUT',
        scoring_formula_version: 'v1-equal-weight-2026-09-03'
      }
    };
  }

  const factors = data.ai_extracted_factors;

  let weightedSum = 0;
  let countUsed = 0;

  directFactors.forEach((key) => {
    const val = numericEstimate(factors[key]);
    if (val !== null) {
      weightedSum += val;
      countUsed += 1;
    }
  });

  inverseFactors.forEach((key) => {
    const val = numericEstimate(factors[key]);
    if (val !== null) {
      weightedSum += (10 - val);
      countUsed += 1;
    }
  });

  const opportunityScore =
    countUsed > 0 ? Math.round((weightedSum / countUsed) * 10) : null;

  const opportunityScoreStatus =
    countUsed === totalFactorsConsidered
      ? 'FULL_COVERAGE'
      : countUsed > 0
      ? 'PARTIAL_COVERAGE'
      : 'INSUFFICIENT_DATA';

  let evidenceConfidence;
  let evidenceConfidenceStatus;

  if (data.is_synthetic) {
    evidenceConfidence = 0;
    evidenceConfidenceStatus = 'SYNTHETIC_TEST_ONLY';
  } else {
    const directnessText = String(
      factors.evidence_directness?.estimate || ''
    ).toLowerCase();

    let directnessScore = 3;
    if (/hypothesis|assumption|no evidence|speculat/.test(directnessText)) {
      directnessScore = 1;
    } else if (/request|inquiry|interest/.test(directnessText)) {
      directnessScore = 5;
    } else if (/transaction|payment|budget|contract|purchase/.test(directnessText)) {
      directnessScore = 9;
    }

    const sampleSizeRaw = factors.evidence_sample_size?.estimate;
    const sampleSize = typeof sampleSizeRaw === 'number' ? sampleSizeRaw : 0;
    const sampleSizeScore = Math.min(sampleSize, 10);

    const sourceMissingPenalty = data.evidence_source_missing ? 0 : 10;

    const rawEvidenceAvg = (directnessScore + sampleSizeScore + sourceMissingPenalty) / 3;
    evidenceConfidence = Math.round(rawEvidenceAvg * 10);
    evidenceConfidenceStatus = 'INITIAL_ESTIMATE';
  }

  return {
    json: {
      ...data,
      uor_stage: 'initial_factor_scoring',
      opportunity_score: opportunityScore,
      opportunity_score_status: opportunityScoreStatus,
      scoring_factor_coverage: `${countUsed}/${totalFactorsConsidered}`,
      evidence_confidence: evidenceConfidence,
      evidence_confidence_status: evidenceConfidenceStatus,
      scoring_formula_version: 'v1-equal-weight-2026-09-03'
    }
  };
});

const items = $input.all();

const HIGH_THRESHOLD = 60;

return items.map((item) => {
  const data = item.json;

  const structurallyValid =
    data.intake_valid === true &&
    data.structured_output_valid === true;

  if (!structurallyValid) {
    return {
      json: {
        ...data,
        uor_stage: 'validation',
        validation_status: 'BLOCKED_INCOMPLETE_PIPELINE',
        interpretation: null,
        ready_for_storage: false,
        requires_human_approval_for_execution: true,
        validation_notes: 'Record did not pass intake validation and/or structured output parsing; not eligible for scoring interpretation.'
      }
    };
  }

  const oppScore = data.opportunity_score;
  const evidConf = data.evidence_confidence;

  let interpretation;
  if (oppScore === null || evidConf === null) {
    interpretation = 'INSUFFICIENT_DATA_FOR_INTERPRETATION';
  } else {
    const highOpp = oppScore >= HIGH_THRESHOLD;
    const highEvid = evidConf >= HIGH_THRESHOLD;

    if (highOpp && highEvid) {
      interpretation = 'HIGH-PRIORITY CANDIDATE';
    } else if (highOpp && !highEvid) {
      interpretation = 'PROMISING — REQUIRES VALIDATION';
    } else if (!highOpp && highEvid) {
      interpretation = 'RELIABLY LOW PRIORITY';
    } else {
      interpretation = 'INSUFFICIENT / LOW PRIORITY';
    }
  }

  const validationStatus = data.compliance_review_required
    ? 'COMPLIANCE_REVIEW_REQUIRED'
    : 'VALIDATED';

  return {
    json: {
      ...data,
      uor_stage: 'validation',
      validation_status: validationStatus,
      interpretation,
      interpretation_thresholds: `high >= ${HIGH_THRESHOLD} (v1-equal-weight)`,
      ready_for_storage: true,
      requires_human_approval_for_execution: true,
      validation_notes: data.compliance_review_required
        ? 'Flagged for mandatory compliance review per Section 25/26. This flag is not cleared by any Opportunity Score or Evidence Confidence value.'
        : 'Passed structural validation. Interpretation is decision support only, not an execution authorization (Section 13).'
    }
  };
});

// Node 8a — Build Storage Record
// Maps the validated record onto the Section 16 historical-intelligence schema
// and serializes it as one JSON string, ready for Convert to File.

const record = $input.item.json;

const storageRecord = {
  opportunity_id: record.signal_id ?? null,
  date_discovered: record.signal_date ?? null,
  date_stored: new Date().toISOString(),
  source: record.source_name ?? null,
  source_type: record.source_type ?? null,
  source_url: record.source_url ?? null,
  category: record.opportunity_category ?? null,

  raw_signal: {
    opportunity_title: record.opportunity_title ?? null,
    problem: record.problem ?? null,
    demand_signal: record.demand_signal ?? null,
    market: record.market ?? null,
    geography: record.geography ?? null,
  },

  normalized_opportunity: record.proposed_solution ?? null,

  customer_problem: {
    target_customer: record.target_customer ?? null,
    problem: record.problem ?? null,
  },

  evidence: {
    evidence_notes: record.evidence_notes ?? null,
    evidence_status: record.evidence_status ?? null,
    is_synthetic: record.is_synthetic ?? null,
    evidence_source_missing: record.evidence_source_missing ?? null,
  },
  evidence_confidence: record.evidence_confidence ?? null,
  evidence_confidence_status: record.evidence_confidence_status ?? null,

  scoring_factors: record.ai_extracted_factors ?? null,
  scoring_factor_coverage: record.scoring_factor_coverage ?? null,
  scoring_formula_version: record.scoring_formula_version ?? null,

  final_score: record.opportunity_score ?? null,
  opportunity_score_status: record.opportunity_score_status ?? null,

  tools_required: null,
  existing_capability_match: null,
  estimated_fulfillment_cost: null,
  estimated_revenue_potential_usd: null,
  duplicates_related_opportunities: null,
  demand_cluster: null,
  subsequent_outcome: null,

  action_recommendation: record.interpretation ?? null,
  interpretation_thresholds: record.interpretation_thresholds ?? null,
  status: record.validation_status ?? null,
  ready_for_storage: record.ready_for_storage ?? null,
  requires_human_approval_for_execution: record.requires_human_approval_for_execution ?? null,
  validation_notes: record.validation_notes ?? null,

  compliance_review_required: record.compliance_review_required ?? null,
  compliance_keywords_detected: record.compliance_keywords_detected ?? null,

  full_record: record,
};

if (record.ready_for_storage !== true) {
  return {
    json: {
      storage_skipped: true,
      reason: `ready_for_storage was ${JSON.stringify(record.ready_for_storage)}, expected true`,
      opportunity_id: record.signal_id ?? null,
      validation_status: record.validation_status ?? null,
    },
  };
}

return {
  json: {
    storage_skipped: false,
    opportunity_id: storageRecord.opportunity_id,
        storage_line: JSON.stringify(storageRecord) + "\n",
  },
};
